cation_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "31d2dbb6-962d-5fe3-b10d-53681317919d"}, {"title": "义武军推王郜为留后", "start_year": 895, "end_year": 895, "time_original": "895年十月王处存去世后条；确日未载", "dynasty": "唐", "description": "军中推王处存之子、节度副使王郜为留后。", "phases": [], "location_name": "义武", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "70352098-03bf-5076-b0c7-fc82a4e9c22f"}, {"title": "京兆尹孙偓授兵部侍郎同平章事", "start_year": 895, "end_year": 895, "time_original": "895年十月条；确日未载", "dynasty": "唐", "description": "朝廷以京兆尹、武邑人孙偓为兵部侍郎、同平章事。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ae59508d-4ae5-5305-8e3a-0352156de04a"}, {"title": "王行瑜五千守龙泉，李克用攻之", "start_year": 895, "end_year": 895, "time_original": "895年十月条；确日未载", "dynasty": "唐", "description": "王行瑜用五千精甲守龙泉寨，李克用进攻。", "phases": [], "location_name": "龙泉寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3b6a0542-2b43-5d98-9e09-67fede706524"}, {"title": "李茂贞五千援龙泉，营镇西", "start_year": 895, "end_year": 895, "time_original": "895年十月攻龙泉条；确日未载", "dynasty": "唐", "description": "李茂贞以五千兵救援龙泉寨，营于镇西。", "phases": [], "location_name": "龙泉镇西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d79a8a4c-693a-521c-aac5-fcf9f5b528a5"}, {"title": "李罕之击退凤翔援兵", "start_year": 895, "end_year": 895, "time_original": "895年十月至十一月攻龙泉过程中；确日未另载", "dynasty": "唐", "description": "李罕之攻击凤翔兵，令其败走。", "phases": [], "location_name": "龙泉寨附近"